/**
 * Parity suite for the tool-pruning evidence rule.
 *
 * `tests/parity/toolprune_vectors.json` is generated by the PINNED upstream Python
 * implementation (`tokeneconomizer/plugin/fold.py::enough_evidence`, commit
 * 7042ea89dd5e5ecbc67ad865ad6e256e61be8bf0) through
 * `generate_toolprune_vectors.py`. The vectors are committed, so running the Node suite
 * needs no Python; regenerating them does.
 *
 * This test replays every session/prompt pair through the TypeScript `enoughEvidence`.
 * It SKIPS (rather than fails) when the generated JSON is absent, matching the other
 * parity suites in this directory.
 */
import test from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

import { enoughEvidence } from '../../lib/toolprune/policy.js'

const HERE = dirname(fileURLToPath(import.meta.url))
const VECTORS_PATH = join(HERE, 'toolprune_vectors.json')

function loadVectors() {
  try {
    return JSON.parse(readFileSync(VECTORS_PATH, 'utf8'))
  } catch (error) {
    if (error && (error.code === 'ENOENT' || error.name === 'SyntaxError')) return null
    throw error
  }
}

const data = loadVectors()
const skip = data ? false : 'tests/parity/toolprune_vectors.json missing; run generate_toolprune_vectors.py'

test('tool-pruning vectors were generated from the pinned upstream commit', { skip }, () => {
  assert.equal(data.upstreamCommit, data.expectedCommit, 'the upstream checkout moved; regenerate the vectors')
  assert.equal(data.generatedBy, 'tests/parity/generate_toolprune_vectors.py')
  assert.equal(data.source, 'tokeneconomizer/plugin/fold.py::enough_evidence')
  assert.equal(data.vectorCount, data.vectors.length)
  assert.ok(data.vectors.length >= 1000)
})

test('enough_evidence matches upstream for every session/prompt pair', { skip }, () => {
  const failures = []
  for (const vector of data.vectors) {
    const actual = enoughEvidence(
      { sessions: vector.sessions, prompts: vector.prompts },
      vector.settings,
    )
    if (actual !== vector.expected) {
      failures.push(`${vector.id}: expected ${vector.expected}, got ${actual}`)
    }
  }
  assert.deepEqual(failures, [], `${failures.length} of ${data.vectors.length} evidence vectors differ`)
})

test('the vector grid covers both the prompt rule and the session shortcut', { skip }, () => {
  const hits = data.vectors.filter((vector) => vector.expected)
  assert.ok(hits.some((vector) => vector.settings.toolpruneSessions <= vector.sessions), 'session shortcut covered')
  assert.ok(
    hits.some(
      (vector) =>
        vector.sessions >= vector.settings.toolpruneMinSessions &&
        vector.prompts >= vector.settings.toolpruneEvidence,
    ),
    'prompt evidence covered',
  )
  assert.ok(data.vectors.some((vector) => !vector.expected), 'negative cases covered')
})
